import{_ as l,a0 as s,w as a,s as d,I as r,x as t,a1 as i,A as o,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux中使用rsync——文件和目錄排除列表 | LCTT x X-CMD","titleTemplate":false,"description":"Linux中使用rsync——文件和目錄排除列表 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux中使用rsync——文件和目錄排除列表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux中使用rsync——文件和目錄排除列表 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux","title":"Linux中使用rsync——文件和目錄排除列表","tag":"201412","desc":""},"relativePath":"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux.md","filePath":"[post].md"}'),u={name:"201412/20141030 rsync Command to Exclude a List of Files and Directories in Linux.md"};function x(m,n,c,f,y,L){const e=s("Link");return a(),d("div",null,[n[17]||(n[17]=r("h1",{id:"linux中使用rsync——文件和目錄排除列表",tabindex:"-1"},[t("Linux中使用rsync——文件和目錄排除列表 "),r("a",{class:"header-anchor",href:"#linux中使用rsync——文件和目錄排除列表","aria-label":"Permalink to “Linux中使用rsync——文件和目錄排除列表”"},"​")],-1)),r("p",null,[n[1]||(n[1]=r("strong",null,"rsync",-1)),n[2]||(n[2]=t("是一個十分有用，而且十分流行的linux工具。它用於備份和恢復文件，也用於對比和同步文件。我們已經在前面的文章講述了",-1)),i(e,{href:"http://linux.cn/article-4503-1.html"},{default:o(()=>[...n[0]||(n[0]=[t("如何在Linux下使用rsync",-1)])]),_:1}),n[3]||(n[3]=t("，而今天我們將增加一些更為有用的rsync使用技巧。",-1))]),n[18]||(n[18]=p(`<h3 id="排除文件和目錄列表" tabindex="-1">排除文件和目錄列表 <a class="header-anchor" href="#排除文件和目錄列表" aria-label="Permalink to “排除文件和目錄列表”">​</a></h3><p>有時候，當我們做大量同步的時候，我們可能想要從同步的文件和目錄中排除一個文件和目錄的列表。一般來説，像設備文件和某些系統文件，或者像臨時文件或者緩存文件這類佔據不必要磁盤空間的文件是不合適同步的，這類文件是我們需要排除的。</p><p>首先，讓我們創建一個名為“excluded”的文件（當然，你想取什麼名都可以），然後將我們想要排除的文件夾或文件寫入該文件，一行一個。在我們的例子中，如果你想要對根分區進行完整的備份，你應該排除一些在啓動時創建的設備目錄和放置臨時文件的目錄，列表看起來像下面這樣：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-excluded.jpg" alt="rsync excluded"></p><p>然後，你可以運行以下命令來備份系統：</p><pre><code>$ sudo rsync -aAXhv --exclude-from=excluded / /mnt/backup
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-exclude-file.jpg" alt="rsync exclude file"></p><h3 id="從命令列排除文件" tabindex="-1">從命令列排除文件 <a class="header-anchor" href="#從命令列排除文件" aria-label="Permalink to “從命令列排除文件”">​</a></h3><p>你也可以從命令列直接排除文件，該方法在你要排除的文件數量較少，並且在你想要將它寫成腳本或加到crontab中又不想腳本或cron依賴於另外一個文件運行時十分有用。</p><p>例如，如果你想要同步/var到一個備份目錄，但是你不想要包含cache和tmp這些通常不會有重要內容的文件夾，你可以使用以下命令：</p><pre><code>$ sudo rsync -aAXhv --exclude={&quot;/var/cache&quot;,&quot;/var/tmp&quot;} /var /home/adrian/var
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/rsync-exclude.jpg" alt="rsync exclude"></p><p>該命令易於在腳本或cron中使用，也不會依賴其它文件。</p><hr>`,14)),r("p",null,[n[5]||(n[5]=t("via: ",-1)),i(e,{href:"http://linoxide.com/linux-command/exclude-files-rsync-examples/"},{default:o(()=>[...n[4]||(n[4]=[t("http://linoxide.com/linux-command/exclude-files-rsync-examples/",-1)])]),_:1})]),r("p",null,[n[9]||(n[9]=t("作者：",-1)),i(e,{href:"http://linoxide.com/author/adriand/"},{default:o(()=>[...n[6]||(n[6]=[t("Adrian Dinu",-1)])]),_:1}),n[10]||(n[10]=t(" 譯者：",-1)),i(e,{href:"https://github.com/GOLinux"},{default:o(()=>[...n[7]||(n[7]=[t("GOLinux",-1)])]),_:1}),n[11]||(n[11]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...n[8]||(n[8]=[t("wxy",-1)])]),_:1})]),r("p",null,[n[14]||(n[14]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[12]||(n[12]=[t("LCTT",-1)])]),_:1}),n[15]||(n[15]=t(" 原創翻譯，",-1)),i(e,{href:"http://linux.cn/"},{default:o(()=>[...n[13]||(n[13]=[t("Linux中國",-1)])]),_:1}),n[16]||(n[16]=t(" 榮譽推出",-1))])])}const b=l(u,[["render",x]]);export{g as __pageData,b as default};
